{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Brigatinib, an anilinopyrimidine kinase inhibitor with a piperazine-containing solubilizing group, has an absolute oral bioavailability of 46% in healthy volunteers, supporting high F for the query's similar anilinopyrimidine/piperazine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, which contains an aminopyrimidine and a piperazine moiety, has a mean absolute oral bioavailability of 98%, indicating that this structural class is generally well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, a small-molecule kinase inhibitor with an aminopyrimidine and basic amine motif, has an estimated absolute bioavailability of 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam, a heteroaromatic oral drug containing piperazine and a lactam-like core, has high oral bioavailability due to almost complete absorption and negligible first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Niraparib, an oral small-molecule anticancer drug, has an absolute oral bioavailability of 72.7%, demonstrating that drug-like heteroaromatic molecules with basic amines can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trametinib, an oral kinase inhibitor, has a least-squares mean absolute bioavailability of 72.3%, supporting high oral F for the query's drug-like oral molecule class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small-molecule oral kinase-inhibitor-like compound with an anilinopyrimidine/piperazine scaffold. Multiple close structural analogs have absolute oral bioavailability of 46–98%, and no transferable evidence supports F < 20%. Therefore the prediction is high (F ≥ 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule is available.",
    "No human PK or absorption data specific to this exact pyrrolopyrimidinone scaffold are provided.",
    "Variable mCPP bioavailability is not transferable because of structural and metabolic differences."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

